import Foundation
import SafeDICore
import Testing
@testable import SafeDITool

struct SafeDIToolCodeGenerationTests: ~Copyable {
	// MARK: Initialization

	init() throws {
		filesToDelete = [URL]()
	}

	deinit {
		for fileToDelete in filesToDelete {
			try! FileManager.default.removeItem(at: fileToDelete)
		}
	}

	// MARK: Code Generation Tests

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_successfullyGeneratesOutputFileWhenNoCodeInput() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.generatedFiles == [:])
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_generatesGuardedRoot_whenConditionIsSuppliedToScan() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public struct NetworkService: Instantiable {
				    public init() {}
				}
				""",
				"""
				#if DEBUG
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    public init(networkService: NetworkService) {
				        self.networkService = networkService
				    }

				    @Instantiated let networkService: NetworkService
				}
				#endif
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			activeCompilationConditions: ["DEBUG"],
		)

		#expect(output.generatedFiles?["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if !(DEBUG)
		#error("SafeDI scanned this module assuming `#if DEBUG` was active, but it is inactive in this compilation. Report the conditions this target compiles with to SafeDITool, as the \\"Reporting active conditions\\" section of the SafeDI manual describes for your build system.")
		#endif

		extension Root {
		    public init() {
		        let networkService = NetworkService()
		        self.init(networkService: networkService)
		    }
		}
		""")
	}

