	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_assertsInactiveCondition_whenGuardedRootIsSkipped() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public struct NetworkService: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    public init(networkService: NetworkService) {
				        self.networkService = networkService
				    }

				    @Instantiated let networkService: NetworkService
				}
				""",
				"""
				#if DEBUG
				@Instantiable(isRoot: true)
				public struct DebugRoot: Instantiable {
				    public init(networkService: NetworkService) {
				        self.networkService = networkService
				    }

				    @Instantiated let networkService: NetworkService
				}
				#endif
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			// The verification compile defines `DEBUG`, so the assertion below fails it on purpose.
			skipCompileVerification: true,
		)

		// The skipped root still gets a file, which holds no code.
		#expect(output.generatedFiles?.keys.sorted() == ["DebugRoot+SafeDI.swift", "Root+SafeDI.swift"])
		#expect(output.generatedFiles?["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		#error("SafeDI scanned this module assuming `#if DEBUG` was inactive, but it is active in this compilation. Report the conditions this target compiles with to SafeDITool, as the \\"Reporting active conditions\\" section of the SafeDI manual describes for your build system.")
		#endif

		extension Root {
		    public init() {
		        let networkService = NetworkService()
		        self.init(networkService: networkService)
		    }
		}
		""")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_wiresGuardedDependency_whenConditionIsActive() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public struct NetworkService: Instantiable {
				    public init() {}
				}
				""",
				"""
				#if STAGING
				@Instantiable
				public struct StagingService: Instantiable {
				    public init() {}
				}
				#endif
				""",
				"""
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    #if STAGING
				    public init(networkService: NetworkService, stagingService: StagingService) {
				        self.networkService = networkService
				        self.stagingService = stagingService
				    }

				    @Instantiated let stagingService: StagingService
				    #else
				    public init(networkService: NetworkService) {
				        self.networkService = networkService
				    }
				    #endif

				    @Instantiated let networkService: NetworkService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			activeCompilationConditions: ["STAGING"],
		)

		#expect(output.generatedFiles?["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if !(STAGING)
		#error("SafeDI scanned this module assuming `#if STAGING` was active, but it is inactive in this compilation. Report the conditions this target compiles with to SafeDITool, as the \\"Reporting active conditions\\" section of the SafeDI manual describes for your build system.")
		#endif

		extension Root {
		    public init() {
		        let stagingService = StagingService()
		        let networkService = NetworkService()
		        self.init(networkService: networkService, stagingService: stagingService)
		    }
		}
		""")
	}

