	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_doesNotWriteExtensionIfRootAlreadyHasEmptyInitializer() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				import Foundation

				public protocol NetworkService {}

				@Instantiable(isRoot: true, fulfillingAdditionalTypes: [NetworkService.self])
				public final class DefaultNetworkService: NetworkService, Instantiable {
				    public init() {}
				    let date: Date = Date()
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		let content = try #require(output.generatedFiles?["DefaultNetworkService+SafeDI.swift"])
		#expect(content.contains("// This file was generated by the SafeDIGenerateDependencyTree build tool plugin."))
		#expect(!content.contains("extension"))
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_writesConvenienceExtensionOnRootOfTree_whenRootIsClass() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public class UIViewController {
				    public init(nibName: String?, bundle: AnyObject?) {}
				    public func pushViewController(_ vc: UIViewController) {}
				}
				""",
				"""
				import Foundation

				public protocol NetworkService {}

				@Instantiable(fulfillingAdditionalTypes: [NetworkService.self])
				public final class DefaultNetworkService: NetworkService, Instantiable {
				    public init() {}

				    let date: Date = Date()
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public final class RootViewController: UIViewController, Instantiable {
				    public init(networkService: NetworkService) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let networkService: NetworkService
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.generatedFiles?["RootViewController+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if canImport(Foundation)
		import Foundation
		#endif

		extension RootViewController {
		    public convenience init() {
		        let networkService: NetworkService = DefaultNetworkService()
		        self.init(networkService: networkService)
		    }
		}
		""")
	}

