	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_writesConvenienceExtensionOnRootOfTree_whenExistentialErasedPropertyResolvesConcreteTypeWithItsOwnDependencies() async throws {
		// The existentially-erased property's concrete type has its own
		// `@Instantiated` dependency, so a nested `__safeDI_...` builder
		// function is emitted. The root's assignment must wrap that builder's
		// return value in the erased type: `AnyView(__safeDI_splashScreenView())`.
		// Without the wrap the assignment fails to typecheck against `AnyView`.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol View {}
				public struct AnyView: View {
				    public init<V: View>(_ view: V) {}
				}
				public struct EmptyView: View {
				    public init() {}
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public struct RootView: Instantiable {
				    public init(splashScreenView: AnyView) {
				        self.splashScreenView = splashScreenView
				    }

				    @Instantiated(fulfilledByType: "SplashScreenView", erasedToConcreteExistential: true) private let splashScreenView: AnyView
				}
				""",
				"""
				@Instantiable
				public struct SplashScreenView: View, Instantiable {
				    public init(theme: Theme) { self.theme = theme }
				    @Instantiated let theme: Theme
				}
				""",
				"""
				@Instantiable
				public struct Theme: Instantiable {
				    public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(try #require(output.generatedFiles?["RootView+SafeDI.swift"]) == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		extension RootView {
		    public init() {
		        func __safeDI_splashScreenView() -> SplashScreenView {
		            let theme = Theme()
		            return SplashScreenView(theme: theme)
		        }
		        let splashScreenView = AnyView(__safeDI_splashScreenView())
		        self.init(splashScreenView: splashScreenView)
		    }
		}
		""")
	}

