		        let childA: ChildA = __safeDI_childA()
		        func __safeDI_childB() -> ChildB {
		            func __safeDI_grandchildBA() -> GrandchildBA {
		                @Sendable func __safeDI_greatGrandchildInstantiator() -> GreatGrandchild {
		                    GreatGrandchild()
