				    public init() {}
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public final class Root: Instantiable {
				    public init(instance: Instance, mid: Mid, leaf: Leaf) { self.instance = instance; self.mid = mid; self.leaf = leaf }
				    @Instantiated let instance: Instance
				    @Instantiated let mid: Mid
				    @Instantiated let leaf: Leaf
				}
				""",
				"""
				@Instantiable
				public final class Mid: Instantiable {
				    public init(instance: Instance, inner: Inner, leaf: Leaf) { self.instance = instance; self.inner = inner; self.leaf = leaf }
				    @Instantiated let instance: Instance
				    @Instantiated let inner: Inner
				    @Instantiated let leaf: Leaf
				}
				""",
				"""
				@Instantiable
				public final class Inner: Instantiable {
				    public init(instance: Instance, leaf: Leaf) { self.instance = instance; self.leaf = leaf }
				    @Instantiated let instance: Instance
				    @Instantiated let leaf: Leaf
				}
				""",
				"""
				@Instantiable
				public final class Leaf: Instantiable {
				    public init(instance: Instance) { self.instance = instance }
				    @Received let instance: Instance
				}
