	mutating func run_writesConvenienceExtensionOnRootOfTree_whenPropertyIsOptionalAndMarkedOnlyIfAvailableAndItIsOnlyAvailableFromSiblingBuiltFromReceiversAncestor() async throws {
		// Root builds `b` and `c`. C receives `b`, and Worker, built inside `b`,
		// receives `c` only if available — so `b` comes first and Worker gets `nil`.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public final class Root: Instantiable {
				    public init(b: B, c: C) { self.b = b; self.c = c }
