		#expect(child.dependencies.map(\.declarationLocation) == [
			Dependency.DeclarationLocation(filePath: output.fixtures["Child.swift"], line: 9, column: 5),
			Dependency.DeclarationLocation(filePath: output.fixtures["Child.swift"], line: 11, column: 5),
			Dependency.DeclarationLocation(filePath: output.fixtures["Child.swift"], line: 12, column: 5),
		])
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_doesNotWriteConvenienceExtensionOnRootOfTree_whenUnexpectedSwiftNodesAreEncountered() async throws {
		// If this test begins to fail after updating Swift, put the below code into an AST parser and see if unexpected nodes are still encountered.
		// The broken syntax must produce UnexpectedNodesSyntax at a level FileVisitor visits (class body, not inside function/variable bodies).
		// On Swift versions lower than 6.3, the class B could not be found because earlier code included parser-breaking syntax.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public final class A: Instantiable {
					public init(b: B) {
						self.b = b
					}

					:::brokenSyntax

					@Instantiated private let b: B
				}

				@Instantiable
				public final class B: Instantiable {
					public init() {}
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		// No roots are declared, so no dependency tree files. But mock files get the error stub.
		#expect(output.dependencyTreeFiles == [:])
		#expect(output.moduleInfo.filesWithUnexpectedNodes != nil)
		// Mock outputs get the error stub so the build system has its expected outputs.
		for (_, content) in output.mockFiles {
			#expect(content.contains("#error"), "Mock outputs should contain #error stub")
		}
	}

