	// MARK: Forwarded properties fulfilling a type's own aliases

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_passesForwardedPropertyToOwnOnlyIfAvailableAlias_whenSiblingWithSameLabelIsBuiltLater() async throws {
		// `Screen`'s alias is fulfilled by the `loggerBuilder` it is forwarded, not by `Root`'s, which is built after `screenBuilder`.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public final class Logger: Instantiable {
				    public init(screenBuilder: Instantiator<Screen>) { self.screenBuilder = screenBuilder }
				    @Received let screenBuilder: Instantiator<Screen>
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public final class Root: Instantiable {
				    public init(screenBuilder: Instantiator<Screen>, loggerBuilder: Instantiator<Logger>) {
				        self.screenBuilder = screenBuilder
				        self.loggerBuilder = loggerBuilder
				    }
				    @Instantiated let screenBuilder: Instantiator<Screen>
				    @Instantiated let loggerBuilder: Instantiator<Logger>
				}
				""",
				"""
				@Instantiable
				public final class Screen: Instantiable {
				    public init(loggerBuilder: Instantiator<Logger>, renamedLoggerBuilder: Instantiator<Logger>?) {
				        self.loggerBuilder = loggerBuilder
				        self.renamedLoggerBuilder = renamedLoggerBuilder
				    }
				    @Forwarded let loggerBuilder: Instantiator<Logger>
				    @Received(fulfilledByDependencyNamed: "loggerBuilder", ofType: Instantiator<Logger>.self, onlyIfAvailable: true) let renamedLoggerBuilder: Instantiator<Logger>?
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.generatedFiles?["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		extension Root {
		    public convenience init() {
		        func __safeDI_screenBuilder(loggerBuilder: Instantiator<Logger>) -> Screen {
		            #sourceLocation(file: "\(output.fixtures["Screen.swift"])", line: 8)
		            let renamedLoggerBuilder: Instantiator<Logger>? = loggerBuilder
		            #sourceLocation()
		            return Screen(loggerBuilder: loggerBuilder, renamedLoggerBuilder: renamedLoggerBuilder)
		        }
		        let screenBuilder = Instantiator<Screen> {
		            __safeDI_screenBuilder(loggerBuilder: $0)
		        }
		        func __safeDI_loggerBuilder() -> Logger {
		            Logger(screenBuilder: screenBuilder)
		        }
		        let loggerBuilder = Instantiator<Logger>(__safeDI_loggerBuilder)
		        self.init(screenBuilder: screenBuilder, loggerBuilder: loggerBuilder)
		    }
		}
		""", "Unexpected output \(output.generatedFiles?["Root+SafeDI.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_createsOnlyIfAvailableAliasAfterItsFulfillingDependency_whenTheDependencysTreeReceivesTheAliasOnlyIfAvailable() async throws {
		// `maybeB` is created once `b` is built; `C`, built inside `b`, is passed `nil` for it.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public final class B: Instantiable {
				    public init(c: C) { self.c = c }
				    @Instantiated let c: C
				}
				""",
				"""
				@Instantiable
				public final class C: Instantiable {
				    public init(maybeB: B?) { self.maybeB = maybeB }
				    @Received(onlyIfAvailable: true) let maybeB: B?
				}
				""",
				"""
				@Instantiable
				public final class Parent: Instantiable {
				    public init(b: B, maybeB: B?) { self.b = b; self.maybeB = maybeB }
				    @Instantiated let b: B
				    @Received(fulfilledByDependencyNamed: "b", ofType: B.self, onlyIfAvailable: true) let maybeB: B?
				}
				""",
				"""
				@Instantiable(isRoot: true)
				public final class Root: Instantiable {
				    public init(parent: Parent) { self.parent = parent }
				    @Instantiated let parent: Parent
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.generatedFiles?["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		extension Root {
		    public convenience init() {
		        func __safeDI_parent() -> Parent {
		            func __safeDI_b() -> B {
		                let c = C(maybeB: nil)
		                return B(c: c)
		            }
		            let b: B = __safeDI_b()
		            #sourceLocation(file: "\(output.fixtures["Parent.swift"])", line: 5)
		            let maybeB: B? = b
		            #sourceLocation()
		            return Parent(b: b, maybeB: maybeB)
		        }
		        let parent: Parent = __safeDI_parent()
		        self.init(parent: parent)
		    }
		}
		""", "Unexpected output \(output.generatedFiles?["Root+SafeDI.swift"] ?? "")")
	}

	// MARK: Instantiable ordering

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_ordersModuleInfoInstantiablesBySourceFilePath_whenFilesFinishParsingOutOfOrder() async throws {
		// `AaaSlowRoot` is large enough that its parse task finishes after the
		// tiny files that sort behind it, so completion order and path order differ.
		let slowRootProperties = (0..<400).map { index in
			"    @Instantiated let dependency\(index): Leaf\(index)"
		}.joined(separator: "\n")
		let slowRootInitializerParameters = (0..<400).map { index in
			"dependency\(index): Leaf\(index)"
		}.joined(separator: ", ")
		let leafFiles = (0..<400).map { index in
			"""
			@Instantiable
			public struct Leaf\(index): Instantiable {
			    public init() {}
			}
			"""
		}
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public struct AaaSlowRoot: Instantiable {
				    public init(\(slowRootInitializerParameters)) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				\(slowRootProperties)
				}
				""",
			] + leafFiles,
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			skipCompileVerification: true,
		)

		let sourceFilePaths = output.moduleInfo.instantiables.compactMap(\.sourceFilePath)
		#expect(sourceFilePaths.count == 401)
		#expect(sourceFilePaths == sourceFilePaths.sorted(), "Instantiables were not ordered by source file path: \(sourceFilePaths.prefix(5))")
	}

	// MARK: Received dependency validation

	// The time limit only turns a hang into a failure, so it sits far above any scheduling delay:
	// this test does a fraction of a second of work, but on a loaded CI runner it can wait more
	// than a minute behind the rest of the suite.
	@Test(.timeLimit(.minutes(10)))
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_generatesCodeWithinTimeLimit_whenReceivedDependenciesFormDeepChainOfDiamonds() async throws {
		// Each service receives the two services before it and the service at half its index.
		// The number of distinct received-dependency paths from the last service grows
		// exponentially with the service count, while the number of services does not.
		// Walking every path took about 1.66 times longer per added service (23 seconds at 30
		// services), so at this count it would take tens of thousands of years on any hardware.
		let serviceCount = 80
		let serviceFiles = (0..<serviceCount).map { index in
			let receivedIndices = Set([index - 1, index - 2, index / 2])
				.filter { $0 >= 0 && $0 < index }
				.sorted()
			let initializerParameters = receivedIndices.map { "service\($0): Service\($0)" }.joined(separator: ", ")
			let receivedProperties = receivedIndices.map { "    @Received let service\($0): Service\($0)" }.joined(separator: "\n")
			return """
			@Instantiable
			public struct Service\(index): Instantiable {
			    public init(\(initializerParameters)) {
			        fatalError("SafeDI doesn't inspect the initializer body")
			    }

			\(receivedProperties)
			}
			"""
		}
		let rootInitializerParameters = (0..<serviceCount).map { "service\($0): Service\($0)" }.joined(separator: ", ")
		let rootProperties = (0..<serviceCount).map { "    @Instantiated let service\($0): Service\($0)" }.joined(separator: "\n")
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    public init(\(rootInitializerParameters)) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				\(rootProperties)
				}
				""",
			] + serviceFiles,
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			skipCompileVerification: true,
		)

		#expect(output.dependencyTreeFiles.keys.sorted() == ["Root+SafeDI.swift"])
		#expect(output.mockFiles.isEmpty)
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_generatesCode_whenInstantiatorReceivesInstantiatorOfShadowedPropertyThatReceivesIt() async throws {
		// `P` receives `xBuilder`, and `X` receives a `pBuilder`, but not the `pBuilder` that builds this `P`:
		// `xBuilder` is created where `pBuilder` is `M`'s forwarded property, and `Q` creates its own.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    public init(mBuilder: Instantiator<M>) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let mBuilder: Instantiator<M>
				}
				""",
				"""
				@Instantiable
				public struct M: Instantiable {
				    public init(pBuilder: Instantiator<P>, xBuilder: Instantiator<X>, q: Q) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Forwarded let pBuilder: Instantiator<P>
				    @Instantiated let xBuilder: Instantiator<X>
				    @Instantiated let q: Q
				}
				""",
				"""
				@Instantiable
				public struct Q: Instantiable {
				    public init(pBuilder: Instantiator<P>) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let pBuilder: Instantiator<P>
				}
				""",
				"""
				@Instantiable
				public struct P: Instantiable {
				    public init(xBuilder: Instantiator<X>) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Received let xBuilder: Instantiator<X>
				}
				""",
				"""
				@Instantiable
				public struct X: Instantiable {
				    public init(pBuilder: Instantiator<P>) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Received let pBuilder: Instantiator<P>
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.dependencyTreeFiles["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		extension Root {
		    public init() {
		        func __safeDI_mBuilder(pBuilder: Instantiator<P>) -> M {
		            func __safeDI_xBuilder() -> X {
		                X(pBuilder: pBuilder)
		            }
		            let xBuilder = Instantiator<X>(__safeDI_xBuilder)
		            func __safeDI_q() -> Q {
		                func __safeDI_pBuilder() -> P {
		                    P(xBuilder: xBuilder)
		                }
		                let pBuilder = Instantiator<P>(__safeDI_pBuilder)
		                return Q(pBuilder: pBuilder)
		            }
		            let q: Q = __safeDI_q()
		            return M(pBuilder: pBuilder, xBuilder: xBuilder, q: q)
		        }
		        let mBuilder = Instantiator<M> {
		            __safeDI_mBuilder(pBuilder: $0)
		        }
		        self.init(mBuilder: mBuilder)
		    }
		}
		""")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func run_generatesCodeWithSiblingUnavailable_whenItIsReceivedOnlyIfAvailableInsideLazyCycleOfSiblingThatReceivesIt() async throws {
		// `B` and `C` instantiate one another lazily, and `C` receives `aBuilder` only if available, so
		// `bBuilder` is built first, with `aBuilder` unavailable, and `aBuilder` receives it.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true)
				public struct Root: Instantiable {
				    public init(aBuilder: Instantiator<A>, bBuilder: Instantiator<B>) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let aBuilder: Instantiator<A>
				    @Instantiated let bBuilder: Instantiator<B>
				}
				""",
				"""
				@Instantiable
				public struct A: Instantiable {
				    public init(bBuilder: Instantiator<B>) { self.bBuilder = bBuilder }
				    @Received let bBuilder: Instantiator<B>
				}
				""",
				"""
				@Instantiable
				public struct B: Instantiable {
				    public init(innerCBuilder: Instantiator<C>) { self.innerCBuilder = innerCBuilder }
				    @Instantiated let innerCBuilder: Instantiator<C>
				}
				""",
				"""
				@Instantiable
				public struct C: Instantiable {
				    public init(innerBBuilder: Instantiator<B>, aBuilder: Instantiator<A>?) {
				        fatalError("SafeDI doesn't inspect the initializer body")
				    }

				    @Instantiated let innerBBuilder: Instantiator<B>
				    @Received(onlyIfAvailable: true) let aBuilder: Instantiator<A>?
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.dependencyTreeFiles["Root+SafeDI.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		extension Root {
		    public init() {
		        func __safeDI_bBuilder() -> B {
		            func __safeDI_innerCBuilder() -> C {
		                func __safeDI_innerBBuilder() -> B {
		                    let innerCBuilder = Instantiator<C>(__safeDI_innerCBuilder)
		                    return B(innerCBuilder: innerCBuilder)
		                }
		                let innerBBuilder = Instantiator<B>(__safeDI_innerBBuilder)
		                return C(innerBBuilder: innerBBuilder, aBuilder: nil)
		            }
		            let innerCBuilder = Instantiator<C>(__safeDI_innerCBuilder)
		            return B(innerCBuilder: innerCBuilder)
		        }
		        let bBuilder = Instantiator<B>(__safeDI_bBuilder)
		        func __safeDI_aBuilder() -> A {
		            A(bBuilder: bBuilder)
		        }
		        let aBuilder = Instantiator<A>(__safeDI_aBuilder)
		        self.init(aBuilder: aBuilder, bBuilder: bBuilder)
		    }
		}
		""")
	}

